"""ds4_moe_hip: hand-written MXFP4 MoE decode path for gfx1151.

Replaces UnfusedOAITritonExperts' two matmul_ogs calls plus the activation()
between them (gemm1, SILU+clamp, gemm2+scatter) for small-M decode.

THE ACTIVATION IS SILU WITH A CLAMP, NOT THE GPT-OSS SWIGLU. The serve picks
the TRITON_UNFUSED mxfp4 backend (confirmed in the worker log: "Using
'TRITON_UNFUSED' Mxfp4 MoE backend"), so the epilogue is swiglu_limit_func:
CONCATENATED gate||up halves, gate clamped to max=limit, up to [-limit, limit],
then silu(gate)*up -- with limit = gemm1_clamp_limit = config.swiglu_limit =
10.0. There is no alpha and no (up+1) bias; those belong to SWIGLUOAI, which is
a different activation this kernel deliberately refuses (see eligible()).
Dropping the clamp is not a rounding difference -- it is a different function,
and the output is wrong by orders of magnitude rather than by a few ULPs.

Accuracy against the path it replaces sits at the output dtype's resolution:
the largest observed disagreement is one bf16 ULP at the output peak, i.e. the
dtype, not kernel error.

WHY THE LAYOUT CHECK IS LOUD: an earlier kernel here shipped and never executed
once, because vLLM pads weight rows and its eligibility test asked for
is_contiguous() -- so it silently returned False for every weight in the serve
while looking healthy. This module therefore validates the real shapes and
strides on first use, refuses to run on any mismatch, and records why in
`disabled_reason`.
"""
import ctypes
import os

import torch

_LIB_PATHS = [
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libds4moe.so"),
    "/opt/venv/lib64/python3.12/site-packages/libds4moe.so",
]

_lib = None
_checked: dict = {}
_plans: dict = {}
disabled_reason = None
calls = 0

MAX_M = 8          # entries carry at most NT tokens; M above this is prefill


def _load():
    global _lib, disabled_reason
    if _lib is None:
        for p in _LIB_PATHS:
            if os.path.exists(p):
                _lib = ctypes.CDLL(p)
                break
        if _lib is None:
            disabled_reason = "libds4moe.so not found"
            return None
        _lib.ds4_moe_build_entries.restype = ctypes.c_int
        _lib.ds4_moe_build_entries.argtypes = (
            [ctypes.c_void_p] * 7 + [ctypes.c_int] * 3 + [ctypes.c_void_p])
        _lib.ds4_moe_gemm1.restype = ctypes.c_int
        _lib.ds4_moe_gemm1.argtypes = (
            [ctypes.c_void_p] * 8 + [ctypes.c_int] * 3 +
            [ctypes.c_float] * 2 + [ctypes.c_void_p])
        _lib.ds4_moe_gemm2.restype = ctypes.c_int
        _lib.ds4_moe_gemm2.argtypes = (
            [ctypes.c_void_p] * 9 + [ctypes.c_int] * 3 + [ctypes.c_void_p])
        _lib.ds4_moe_finish.restype = ctypes.c_int
        _lib.ds4_moe_finish.argtypes = (
            [ctypes.c_void_p] * 2 + [ctypes.c_int] * 3 + [ctypes.c_void_p])
    return _lib


def _raw(t):
    """The torch tensor behind a triton_kernels wrapper (or a plain tensor)."""
    for attr in ("storage", "handle"):
        o = getattr(t, attr, None)
        if o is not None:
            d = getattr(o, "data", o)
            if isinstance(d, torch.Tensor):
                return d
    return t if isinstance(t, torch.Tensor) else None


def _layout_ok(vt, st, E, N, K, tag):
    """_swizzle_mxfp4 hands triton a transpose_(-2,-1) VIEW; the memory beneath
    is [E,N,K/2] (values) and [E,N,K/32] (scales), contiguous per output row.
    Confirm exactly that before using a pointer as if it were."""
    global disabled_reason
    if vt is None or st is None:
        disabled_reason = f"{tag}: could not reach the raw tensor"
        return False
    if vt.dtype != torch.uint8 or st.dtype != torch.uint8:
        disabled_reason = f"{tag}: dtypes {vt.dtype}/{st.dtype}, expected uint8"
        return False
    want_v = ((E, K // 2, N), (N * K // 2, 1, K // 2))
    want_s = ((E, K // 32, N), (N * K // 32, 1, K // 32))
    got_v = (tuple(vt.shape), tuple(vt.stride()))
    got_s = (tuple(st.shape), tuple(st.stride()))
    if got_v != want_v:
        disabled_reason = f"{tag} values: got {got_v}, expected {want_v}"
        return False
    if got_s != want_s:
        disabled_reason = f"{tag} scales: got {got_s}, expected {want_s}"
        return False
    return True


def _clamp_limit(quant_config):
    """The clamp the serve's own activation() would apply.

    UnfusedOAITritonExperts.activation() sends MoEActivation.SILU with a
    non-None gemm1_clamp_limit to swiglu_limit_func, which clamps gate to
    max=limit and up to [-limit, limit] before silu(gate)*up. None means the
    unclamped silu_and_mul; the kernel reads limit <= 0 as exactly that.
    """
    lim = getattr(quant_config, "gemm1_clamp_limit", None)
    return 0.0 if lim is None else float(lim)


def eligible(M, hidden_states, w1, w2, output, quant_config, activation=None):
    """activation is the MoEActivation the layer was built with. The epilogue
    below implements SILU (concatenated gate||up halves, optional clamp) only --
    NOT the gpt-oss SWIGLUOAI form (interleaved, alpha=1.702, up+1 bias), which
    is a different function entirely. Refuse anything we cannot name as SILU."""
    global disabled_reason
    if disabled_reason is not None:
        return False
    if _load() is None:
        return False
    if activation is not None:
        # exact match: SILU_NO_MUL and SWIGLUOAI are both different functions
        name = getattr(activation, "name", str(activation)).upper()
        if name != "SILU":
            disabled_reason = f"activation {name} is not SILU"
            return False
    if not (1 <= M <= MAX_M):
        return False
    if hidden_states.dtype != torch.bfloat16 or not hidden_states.is_contiguous():
        return False
    # the finish kernel writes M*N2 bf16 straight into output's storage
    if output.dtype != torch.bfloat16 or not output.is_contiguous():
        return False
    # the kernel folds no bias into its epilogue
    if getattr(quant_config, "w1_bias", None) is not None:
        disabled_reason = "w1_bias is not None"
        return False
    if getattr(quant_config, "w2_bias", None) is not None:
        disabled_reason = "w2_bias is not None"
        return False

    key = (id(w1), id(w2))
    ok = _checked.get(key)
    if ok is None:
        v1, v2 = _raw(w1), _raw(w2)
        s1 = _raw(getattr(quant_config.w1_precision, "weight_scale", None))
        s2 = _raw(getattr(quant_config.w2_precision, "weight_scale", None))
        if v1 is None or v2 is None:
            disabled_reason = "could not reach raw weight tensors"
            return False
        E = v1.shape[0]
        N1, K1 = v1.shape[2], v1.shape[1] * 2      # wrapper is [E, K/2, N]
        N2, K2 = v2.shape[2], v2.shape[1] * 2
        ok = (_layout_ok(v1, s1, E, N1, K1, "w1")
              and _layout_ok(v2, s2, E, N2, K2, "w2")
              and N1 % 8 == 0 and N2 % 32 == 0 and K1 % 512 == 0 and K2 % 512 == 0
              and N1 // 2 == K2                    # swiglu halves N1 into K2
              and output.numel() >= M * N2)
        _checked[key] = ok
        if not ok and disabled_reason is None:
            disabled_reason = "shape constraints not met"
    return bool(ok)


def _plan(w1, w2, quant_config, M, topk, dev):
    """Everything the hot path needs, resolved once per (weights, M, topk).

    The per-call Python -- _raw() attribute chains, shape indexing, buffer
    allocation -- costs more per layer than the kernels save, and it runs on
    every layer of every step. The hot path below must be four ctypes calls
    and nothing else.
    """
    key = (id(w1), id(w2), M, topk, str(dev))
    pl = _plans.get(key)
    if pl is not None:
        return pl
    v1, v2 = _raw(w1), _raw(w2)
    s1 = _raw(quant_config.w1_precision.weight_scale)
    s2 = _raw(quant_config.w2_precision.weight_scale)
    N1, K1 = v1.shape[2], v1.shape[1] * 2
    N2, K2 = v2.shape[2], v2.shape[1] * 2
    P = M * topk
    bufs = dict(
        eidx=torch.empty(P, dtype=torch.int32, device=dev),
        en=torch.empty(P, dtype=torch.int32, device=dev),
        etok=torch.empty(P * 8, dtype=torch.int32, device=dev),
        eslot=torch.empty(P * 8, dtype=torch.int32, device=dev),
        egam=torch.empty(P * 8, dtype=torch.float32, device=dev),
        ic=torch.empty(P + 1, N1 // 2, dtype=torch.bfloat16, device=dev),
        # [P+1, N2]: one row per (token, expert) slot, plus the scratch row
        # the padded slots alias. gemm2 stores into these WITHOUT atomics and
        # moe_reduce_slots sums each token's topk rows in slot order.
        of32=torch.empty(P + 1, N2, dtype=torch.float32, device=dev),
    )
    pl = dict(
        bufs=bufs, of32=bufs["of32"], P=P, topk=topk, N1=N1, K1=K1, N2=N2, K2=K2,
        pv1=v1.data_ptr(), pv2=v2.data_ptr(),
        ps1=s1.data_ptr(), ps2=s2.data_ptr(),
        peidx=bufs["eidx"].data_ptr(), pen=bufs["en"].data_ptr(),
        petok=bufs["etok"].data_ptr(), peslot=bufs["eslot"].data_ptr(),
        pegam=bufs["egam"].data_ptr(), pic=bufs["ic"].data_ptr(),
        pof32=bufs["of32"].data_ptr(), M=M,
        # keep the tensors alive; data_ptr() alone would not
        _keep=(v1, v2, s1, s2),
    )
    _plans[key] = pl
    return pl


def fused_experts(output, hidden_states, w1, w2, topk_weights, topk_ids,
                  quant_config, swiglu_alpha=1.702, swiglu_limit=None, tag=""):
    """output[M,K] += sum over the token's experts. Caller checked eligible().

    swiglu_limit defaults to the value the serve itself would clamp with --
    quant_config.gemm1_clamp_limit, which for DeepSeek-V4-Flash is
    config.swiglu_limit = 10.0. Pass a float only to override it.
    """
    global calls
    lib = _lib
    if swiglu_limit is None:
        swiglu_limit = _clamp_limit(quant_config)
    M = hidden_states.shape[0]
    pl = _plan(w1, w2, quant_config, M, topk_ids.shape[1], hidden_states.device)
    st = torch.cuda.current_stream().cuda_stream
    # every real slot row is fully written by its entry, so only the scratch
    # row (which nothing reads) would be stale; zeroing keeps a partially
    # populated buffer from ever being summed if an entry is skipped.
    pl["of32"].zero_()

    gam = topk_weights.reshape(-1)
    if gam.dtype != torch.float32 or not gam.is_contiguous():
        gam = gam.to(torch.float32).contiguous()
    ids = topk_ids.reshape(-1)
    if not ids.is_contiguous():
        ids = ids.contiguous()

    rc = lib.ds4_moe_build_entries(
        ids.data_ptr(), gam.data_ptr(), pl["peidx"], pl["pen"], pl["petok"],
        pl["peslot"], pl["pegam"], pl["P"], pl["topk"],
        1 if ids.dtype == torch.int64 else 0, st)
    if rc != 0:
        raise RuntimeError(f"ds4_moe_build_entries rc={rc}")
    rc = lib.ds4_moe_gemm1(
        hidden_states.data_ptr(), pl["pv1"], pl["ps1"], pl["peidx"], pl["pen"],
        pl["petok"], pl["peslot"], pl["pic"], pl["P"], pl["N1"], pl["K1"],
        swiglu_alpha, swiglu_limit, st)
    if rc != 0:
        raise RuntimeError(f"ds4_moe_gemm1 rc={rc}")
    rc = lib.ds4_moe_gemm2(
        pl["pic"], pl["pv2"], pl["ps2"], pl["peidx"], pl["pen"], pl["petok"],
        pl["peslot"], pl["pegam"], pl["pof32"], pl["P"], pl["N2"], pl["K2"], st)
    if rc != 0:
        raise RuntimeError(f"ds4_moe_gemm2 rc={rc}")
    rc = lib.ds4_moe_finish(pl["pof32"], output.data_ptr(), pl["M"],
                            pl["N2"], pl["topk"], st)
    if rc != 0:
        raise RuntimeError(f"ds4_moe_finish rc={rc}")
    if calls == 0:                     # prove which call site actually runs
        try:
            with open("/var/tmp/ds4_moe_hip_active.txt", "a") as f:
                f.write(f"{tag} M={hidden_states.shape[0]} "
                        f"topk={topk_ids.shape[1]} N1={pl['N1']} K1={pl['K1']} "
                        f"N2={pl['N2']} K2={pl['K2']}\n")
        except OSError:
            pass
    calls += 1
    return output
